# 计算正整数 x 的数位能量 (各位数字之和)
def digit_energy(x):
    s = 0
    while x > 0:
        s += x % 10
        x //= 10
    return s

def main():
    N, K = map(int, input().split())

    # 枚举的下界（不能小于 1）
    start = max(1, N - K)
    # 枚举的上界
    end = N + K

    max_energy = 0
    # 遍历所有可达位置，记录最大的数位能量
    for x in range(start, end + 1):
        e = digit_energy(x)
        if e > max_energy:
            max_energy = e

    print(max_energy)

if __name__ == "__main__":
    main()
```

